  // ---------------- registers ----------------
  logic [10:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [10:0] r_CFG;   // 12'h014 CFG
  logic [15:0] r_SID;   // 12'h018 SID
  logic [31:0] r_IVFIX0;   // 12'h01C IVFIX0
  logic [31:0] r_IVFIX1;   // 12'h020 IVFIX1
  logic [6:0] r_KM;   // 12'h024 KM
  logic [31:0] r_KEY0;   // 12'h028 KEY0
  logic [31:0] r_KEY1;   // 12'h02C KEY1
  logic [31:0] r_KEY2;   // 12'h030 KEY2
  logic [31:0] r_KEY3;   // 12'h034 KEY3
  logic [31:0] r_KEY4;   // 12'h038 KEY4
  logic [31:0] r_KEY5;   // 12'h03C KEY5
  logic [31:0] r_KEY6;   // 12'h040 KEY6
  logic [31:0] r_KEY7;   // 12'h044 KEY7
  logic [3:0] p_CMD;   // 12'h048 CMD (pulses)
  logic [31:0] h_TX0;   // 12'h04C TX0 holding register
  logic [31:0] h_TX1;   // 12'h050 TX1 holding register
  logic [31:0] h_TX2;   // 12'h054 TX2 holding register
  logic [31:0] h_TX3;   // 12'h058 TX3 holding register
  logic [11:0] h_TX4;   // 12'h05C TX4 holding register
  logic [31:0] h_TXO0;   // 12'h060 TXO0 holding register
  logic [31:0] h_TXO1;   // 12'h064 TXO1 holding register
  logic [31:0] h_TXO2;   // 12'h068 TXO2 holding register
  logic [31:0] h_TXO3;   // 12'h06C TXO3 holding register
  logic [9:0] h_TXO4;   // 12'h070 TXO4 holding register
  logic [31:0] h_RX0;   // 12'h074 RX0 holding register
  logic [31:0] h_RX1;   // 12'h078 RX1 holding register
  logic [31:0] h_RX2;   // 12'h07C RX2 holding register
  logic [31:0] h_RX3;   // 12'h080 RX3 holding register
  logic [10:0] h_RX4;   // 12'h084 RX4 holding register
  logic [31:0] h_RXO0;   // 12'h088 RXO0 holding register
  logic [31:0] h_RXO1;   // 12'h08C RXO1 holding register
  logic [31:0] h_RXO2;   // 12'h090 RXO2 holding register
  logic [31:0] h_RXO3;   // 12'h094 RXO3 holding register
  logic [9:0] h_RXO4;   // 12'h098 RXO4 holding register
  logic full_TX;
  logic avail_TXO;
  logic full_RX;
  logic avail_RXO;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
