      r_SID <= 16'h0;
      r_IVFIX0 <= 32'h0;
      r_IVFIX1 <= 32'h0;
      r_KM <= 7'h0;
      r_KEY0 <= 32'h0;
      r_KEY1 <= 32'h0;
      r_KEY2 <= 32'h0;
      r_KEY3 <= 32'h0;
      r_KEY4 <= 32'h0;
      r_KEY5 <= 32'h0;
      r_KEY6 <= 32'h0;
