  assign c_s_en = r_CFG[1:0];
  assign c_s_cm = r_CFG[3:2];
  assign c_cm_agg = r_CFG[10:4];
  assign c_s_id = r_SID[15:0];
  assign c_s_ivfix[31:0] = r_IVFIX0[31:0];
