  assign c_km_sid = r_KM[2:1];
  assign c_km_ks = r_KM[3:3];
  assign c_km_sub = r_KM[5:4];
  assign c_km_sel = r_KM[6:6];
  assign c_km_key[31:0] = r_KEY0[31:0];
  assign c_km_key[63:32] = r_KEY1[31:0];
  assign c_km_key[95:64] = r_KEY2[31:0];
  assign c_km_key[127:96] = r_KEY3[31:0];
