  assign c_tx_data[95:64] = h_TX2[31:0];
  assign c_tx_data[127:96] = h_TX3[31:0];
  assign c_tx_bytes[4:0] = h_TX4[4:0];
  assign c_tx_hdr = h_TX4[5:5];
  assign c_tx_last = h_TX4[6:6];
  assign c_tx_ide = h_TX4[7:7];
  assign c_tx_sid[1:0] = h_TX4[9:8];
  assign c_tx_sub[1:0] = h_TX4[11:10];
  assign c_rx_data[31:0] = h_RX0[31:0];
  assign c_rx_data[63:32] = h_RX1[31:0];
  assign c_rx_data[95:64] = h_RX2[31:0];
  assign c_rx_data[127:96] = h_RX3[31:0];
  assign c_rx_bytes[4:0] = h_RX4[4:0];
  assign c_rx_kind[1:0] = h_RX4[6:5];
  assign c_rx_last = h_RX4[7:7];
  assign c_rx_cm = h_RX4[8:8];
  assign c_rx_sid[1:0] = h_RX4[10:9];
  assign c_tx_valid = full_TX;
  assign c_txo_ready = ~avail_TXO | (rd & hit[28]);
  assign c_rx_valid = full_RX;
  assign c_rxo_ready = ~avail_RXO | (rd & hit[38]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_done;
    irq_set[1] = c_tx_err;
    irq_set[2] = c_rx_done;
    irq_set[3] = c_rx_err;
    irq_set[4] = c_km_err;
    irq_set[5] = full_TX & c_tx_ready;
    irq_set[6] = wr & (hit[19] | hit[20] | hit[21] | hit[22] | hit[23]) & full_TX;
    irq_set[7] = c_txo_valid & (~avail_TXO | (rd & hit[28]));
    irq_set[8] = full_RX & c_rx_ready;
    irq_set[9] = wr & (hit[29] | hit[30] | hit[31] | hit[32] | hit[33]) & full_RX;
