  end
  assign irq = |(irq_status & irq_enable);
  wire [3:0] flags = {avail_RXO, full_RX, avail_TXO, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG);
      10'd6: apb_rdata = 32'(r_SID);
      10'd7: apb_rdata = 32'(r_IVFIX0);
      10'd8: apb_rdata = 32'(r_IVFIX1);
      10'd9: apb_rdata = 32'(r_KM);
      10'd19: apb_rdata = 32'(h_TX0);
      10'd20: apb_rdata = 32'(h_TX1);
      10'd21: apb_rdata = 32'(h_TX2);
      10'd22: apb_rdata = 32'(h_TX3);
      10'd23: apb_rdata = 32'(h_TX4);
      10'd24: apb_rdata = 32'(h_TXO0);
      10'd25: apb_rdata = 32'(h_TXO1);
      10'd26: apb_rdata = 32'(h_TXO2);
      10'd27: apb_rdata = 32'(h_TXO3);
      10'd28: apb_rdata = 32'(h_TXO4);
      10'd29: apb_rdata = 32'(h_RX0);
      10'd30: apb_rdata = 32'(h_RX1);
      10'd31: apb_rdata = 32'(h_RX2);
      10'd32: apb_rdata = 32'(h_RX3);
      10'd33: apb_rdata = 32'(h_RX4);
      10'd34: apb_rdata = 32'(h_RXO0);
      10'd35: apb_rdata = 32'(h_RXO1);
      10'd36: apb_rdata = 32'(h_RXO2);
      10'd37: apb_rdata = 32'(h_RXO3);
      10'd38: apb_rdata = 32'(h_RXO4);
      10'd39: apb_rdata = 32'({c_rx_eid, c_rx_code, c_tx_esid, c_tx_code, c_km_code, c_rx_busy, c_tx_busy, c_ks_rx, c_ks_tx, c_sec_rx, c_sec_tx});
      10'd40: apb_rdata = 32'({c_kv_rx, c_kv_tx});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
